alter table health_scores drop constraint if exists health_scores_score_type_check;
alter table health_scores add constraint health_scores_score_type_check check (score_type in ('energy_balance','body_support','nourishment','recovery','physical_wellness_index','active_performance','stress_resilience','nutrition','clinical','activity','sleep','calm','overall','stress_recovery','cycle','health_intelligence'));
create table if not exists daily_health_aggregates(id text primary key,user_id text not null references users(id) on delete cascade,client_id text not null,aggregate_date date not null,metric_type text not null,aggregation_method text not null,value numeric not null,unit text not null,source_observation_ids jsonb not null default '[]'::jsonb,source_count integer not null,freshness text not null,calculation_version text not null,calculated_at timestamptz not null default now(),foreign key(client_id,user_id) references fiteatsy_clients(id,account_user_id) on delete cascade,unique(client_id,aggregate_date,metric_type,calculation_version));
create index if not exists daily_health_aggregates_client_date_idx on daily_health_aggregates(client_id,aggregate_date desc);
